import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md","lastUpdated":1790186719000}'),r={name:"compatibility.md"};function c(n,t,s,i,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>What runs where, what converts in which direction, and what is missing. All of it is exercised by the test suites under <code>python/</code> and <code>tests/</code>.</p><h2 id="backends" tabindex="-1">Backends <a class="header-anchor" href="#backends" aria-label="Permalink to &quot;Backends&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>Call</th><th>Notes</th></tr></thead><tbody><tr><td>PyTorch</td><td><code>linnet_torch.load</code></td><td>interpreted Core IR, or generated source with <code>compile=True</code>; <code>numerics=&quot;equivalent&quot;</code> selects native kernels; <code>trainable=True</code> for autograd</td></tr><tr><td>JAX</td><td><code>linnet_jax.load</code>, <code>load_source</code>, <code>load_nnx</code></td><td><code>load</code> compiles StableHLO with XLA (no VJP); <code>load_source</code> runs generated <code>jnp</code> code and differentiates; <code>load_nnx</code> wraps either as a Flax NNX module</td></tr><tr><td>StableHLO</td><td><code>linnet stablehlo --bind ...</code></td><td>static shapes; parameters by <code>linnet.path</code>, state by <code>linnet.state</code> and <code>linnet.states</code></td></tr><tr><td>ONNX</td><td><code>linnet onnx --bind ...</code></td><td>opset 20 text format; parameters as <code>param&lt;N&gt;</code> with metadata, state as <code>state&lt;N&gt;</code> and <code>next_state&lt;N&gt;</code></td></tr></tbody></table><h2 id="importers" tabindex="-1">Importers <a class="header-anchor" href="#importers" aria-label="Permalink to &quot;Importers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Call</th><th>Recovers</th></tr></thead><tbody><tr><td>PyTorch modules</td><td><code>linnet_torch.export_linnet</code></td><td>module tree as blocks and sub arrays; <code>Linear</code>, <code>Embedding</code>, <code>LayerNorm</code>, <code>RMSNorm</code>, softmax, GELU, SiLU as library calls; <code>matmul</code> and <code>einsum</code> as index notation</td></tr><tr><td>JAX functions</td><td><code>linnet_jax.export_linnet</code></td><td>the parameter pytree as blocks; <code>dot_general</code>, <code>reduce</code>, row <code>gather</code>; softmax, sigmoid, silu, gelu, and RMS norm decompositions</td></tr><tr><td>StableHLO text</td><td><code>linnet_jax.import_stablehlo</code></td><td>the same translation for modules produced elsewhere</td></tr><tr><td>ONNX models</td><td><code>linnet_onnx.import_onnx</code></td><td>initializer names as the hierarchy, <code>dim_param</code>s as generics, shape arithmetic folded, the common operators, PyTorch&#39;s RMS norm, SiLU, and softmax decompositions</td></tr></tbody></table><p>Every importer refuses rather than guesses. Unmapped operations stop the import by name; anything dropped is listed in <code>notes</code>.</p><h2 id="real-checkpoints" tabindex="-1">Real checkpoints <a class="header-anchor" href="#real-checkpoints" aria-label="Permalink to &quot;Real checkpoints&quot;">​</a></h2><p>The Llama example loaded with TinyLlama-1.1B&#39;s weights and the GPT-2 example loaded with GPT-2&#39;s weights give the logits <code>transformers</code> gives (within 2e-2 in f32, identical argmax), including decoding through the KV caches. <code>python/linnet_torch/tests/test_hf_checkpoints.py</code> runs the comparison with <code>LINNET_HF_TESTS=1</code>.</p><h2 id="language-features-by-backend" tabindex="-1">Language features by backend <a class="header-anchor" href="#language-features-by-backend" aria-label="Permalink to &quot;Language features by backend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>PyTorch</th><th>JAX and StableHLO</th><th>ONNX</th></tr></thead><tbody><tr><td>Symbolic shapes</td><td>bound at load and from inputs</td><td>bound per compile</td><td>bound per export</td></tr><tr><td><code>static for</code> (sub arrays, integer ranges)</td><td>yes</td><td>unrolled</td><td>unrolled</td></tr><tr><td><code>while</code></td><td>yes, also in generated source</td><td><code>stablehlo.while</code>, <code>lax.while_loop</code></td><td><code>Loop</code></td></tr><tr><td>Index notation and reductions</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td>Optional parameters</td><td>yes</td><td><code>--optionals</code></td><td>yes</td></tr><tr><td>Enum constants and <code>match</code></td><td>yes</td><td>folded</td><td>folded</td></tr><tr><td>Tuple results</td><td>yes</td><td>yes</td><td>one output per element</td></tr><tr><td><code>state</code> members</td><td>buffers, <code>reset_state()</code></td><td>threaded in and out</td><td>threaded in and out</td></tr><tr><td><code>std.random</code></td><td>yes</td><td>yes</td><td>yes (right shifts are logical)</td></tr><tr><td>Training</td><td><code>trainable=True</code></td><td><code>load_source</code> with <code>jax.grad</code></td><td>no</td></tr><tr><td>dtypes</td><td>f16, bf16, f32, f64, i8 to i64, u8, bool</td><td>as the backend supports</td><td>as opset 20 supports</td></tr></tbody></table><h2 id="not-yet" tabindex="-1">Not yet <a class="header-anchor" href="#not-yet" aria-label="Permalink to &quot;Not yet&quot;">​</a></h2><ul><li>A <code>scan</code> that collects per-iteration outputs; data-dependent shapes.</li><li>Importers: <code>erf</code>-based GELU, softmax over an axis other than the last, general gather and scatter, custom calls.</li><li>Quantization schemes beyond per-row int8 and packed int4 (per-group, asymmetric); activation quantization.</li></ul>',13)])])}const u=e(r,[["render",c]]);export{m as __pageData,u as default};
